// ── Unit plan assignment (BR-MET-040/041/042 · BR-CUS-014) ─────────────────

export interface UnitPlanAssignment {
  unit_id: string;
  // The keys `apps/metering/services._apply_unit_plan` actually answers with
  // (its `after` block), field for field. `default_tariff_id` was typed here
  // and never served — DEF-121.
  rate_plan_id: string;
  plan_name: string;
  plan_version: number;
  plan_effective_from: string;
  plan_locked: boolean;
  vacant_standby_auto: boolean;
  history_recorded: boolean; // BR-CUS-013's append-only row is RATING-owned
  // BR-MET-042: a direct unit-level plan edit on an OCCUPIED unit is allowed as
  // an error-correction OVERRIDE — the server returns the warning, the screen
  // SHOWS it. Null when the unit is vacant or had no plan.
  warning: ServerWarning | null;
  // BR-MET-042's occupied-unit override and rating's PO-2026-08-11 backdating
  // warning can BOTH be true of one assignment, so the server also serves them
  // as a list. `warning` stays for existing readers.
  warnings?: ServerWarning[];
}

export interface UnitPlanBulkResult {
  assigned: number;
  failed: number;
  units: UnitPlanAssignment[];
  errors: { unit_id: string; reason: string }[];
}

