  /** BR-REP-008's word for this line's source. */
  type: string;
  /** false = the vocabulary has no word for this source and the RAW source_type
   *  is showing through. A visible defect by design — bucketing an unknown
   *  source under a familiar word hides a new posting contract inside an old
   *  column. */
  type_mapped: boolean;
  /** The source document's UUID, NOT `BL-2607-018204`: a journal line carries
   *  the invoice's id and no module publishes the number read. */
